-- ISOLATED TEST DATABASE ONLY. Synthetic records; rolled back at the end.
BEGIN;
CREATE OR REPLACE FUNCTION public.test_4101_reject(q text, label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 BEGIN EXECUTE q;EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS: % [%]',label,SQLSTATE;RETURN;END;
 RAISE EXCEPTION 'ASSERT FAILED: % should fail',label;
END $$;
SELECT public.test_assert(NOT has_function_privilege('anon','public.dnm_v4101_edit_work(jsonb,uuid)','EXECUTE'),'anonymous diary edit forbidden');
SELECT public.test_assert(NOT has_function_privilege('authenticated','dnm_private.v4101_delete_lot(uuid,text)','EXECUTE'),'private LOT deletion is not directly callable');
DO $$
DECLARE
 admin_id uuid:='11111111-1111-4111-8111-111111111111';
 worker_id uuid:='33333333-3333-4333-8333-333333333333';
 viewer_id uuid:='44444444-4444-4444-8444-444444444444';
 oid uuid; other_order uuid; rid uuid; empty_route uuid; opid uuid; lastid uuid; wid uuid; lastwid uuid; eid uuid; eqid uuid;
 r public.dnm_v4_records; result jsonb; replay jsonb; payload jsonb; steps jsonb; ids jsonb; state_before jsonb;
 key uuid; n int; started timestamptz; log_data jsonb; hist_count int;
BEGIN
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 result:=public.dnm_v4101_save_order(jsonb_build_object('data',jsonb_build_object('production_no','T4101-ORDER','order_type','CIVIL','customer','시험고객','part_no','T4101-BUSH','part_name','시험 부싱','qty',1000,'shop_order_no','SHOP-T4101')),gen_random_uuid());
 oid:=(result->>'id')::uuid;
 SELECT jsonb_agg(jsonb_build_object('code',lpad((s*10)::text,3,'0'),'name','검증공정'||s,'kind','WORK','independent',true)) INTO steps FROM generate_series(1,17) s;
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=oid;
 payload:=jsonb_build_object('order_id',oid,'order_version',r.version,'manager_id',admin_id,'plan_date',(now() AT TIME ZONE 'Asia/Seoul')::date,'total_qty',500,'lot_qty',1,'steps',steps);
 key:=gen_random_uuid();started:=clock_timestamp();result:=public.dnm_v410_split(payload,key);ids:=result->'ids';
 PERFORM public.test_assert((result->>'count')::int=500,'500 LOTs with 17 operations each are created');
 RAISE NOTICE 'CAPACITY: 500 LOT / 8500 operations completed in % seconds',extract(epoch FROM clock_timestamp()-started);
 PERFORM public.test_assert((SELECT count(*) FROM public.dnm_v4_records WHERE kind='operation' AND parent_id IN(SELECT value::text::uuid FROM jsonb_array_elements_text(ids)))=8500,'8500 process instructions persisted');
 replay:=public.dnm_v410_split(payload,key);PERFORM public.test_assert(replay=result,'500-LOT retry is idempotent');
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v410_split(%L::jsonb,gen_random_uuid())',payload||'{"total_qty":501,"lot_qty":1}'),'501 automatic LOTs are rejected');
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v410_split(%L::jsonb,gen_random_uuid())',payload||jsonb_build_object('total_qty',501,'quantities',(SELECT jsonb_agg(1) FROM generate_series(1,501)))),'501 edited LOT quantities are rejected');
 result:=public.dnm_v4101_balances(ARRAY[oid]);
 PERFORM public.test_assert((result->'rows'->0->>'allocated')::int=500 AND (result->'rows'->0->>'remaining')::int=500,'order shows actual allocated and unallocated quantities');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=oid;
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_save_order(%L::jsonb,gen_random_uuid())',jsonb_build_object('id',oid,'version',r.version,'data',r.data||'{"qty":499}')),'order cannot shrink below allocation');
 result:=public.dnm_v4101_save_order(jsonb_build_object('id',oid,'version',r.version,'data',r.data||'{"qty":1200,"heat_code":"H-NEW"}'),gen_random_uuid());
 PERFORM public.test_assert((result->>'remaining')::int=700,'civil order quantity can increase after LOT creation');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=oid;
 payload:=payload||jsonb_build_object('order_version',r.version,'total_qty',700,'lot_qty',350,'steps',steps);
 result:=public.dnm_v410_split(payload,gen_random_uuid());rid:=(result->'ids'->>0)::uuid;empty_route:=(result->'ids'->>1)::uuid;
 PERFORM public.test_assert((result->>'remaining')::int=0,'additional LOTs consume only remaining order quantity');
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v410_split(%L::jsonb,gen_random_uuid())',payload||'{"total_qty":1,"lot_qty":1}'),'all additional creation routes reject over-allocation');
 SELECT id INTO eid FROM public.dnm_v4_records WHERE kind='employee' AND code='EMP-TEST';
 SELECT id INTO eqid FROM public.dnm_v4_records WHERE kind='equipment' LIMIT 1;
 SELECT id INTO opid FROM public.dnm_v4_records WHERE kind='operation' AND parent_id=rid ORDER BY (data->>'seq')::int LIMIT 1;
 SELECT id INTO lastid FROM public.dnm_v4_records WHERE kind='operation' AND parent_id=rid ORDER BY (data->>'seq')::int DESC LIMIT 1;
 UPDATE public.dnm_v4_records SET state='RELEASED' WHERE id=rid;
 UPDATE public.dnm_v4_records SET state='WAIT' WHERE parent_id=rid AND kind='operation';
 log_data:=jsonb_build_object('order_id',oid,'route_id',rid,'production_no','T4101-ORDER','part_no','T4101-BUSH','employee_id',eid,'employee_name','시험작업자','profile_id',worker_id,'manager_id',admin_id,'equipment_id',eqid,
  'start_at',now()-interval '2 hours','end_at',now()-interval '1 hour','work_date',(now() AT TIME ZONE 'Asia/Seoul')::date,'minutes',60,'total',10,'good',9,'defect',1,'note','원작업','memo','원메모');
 SELECT * INTO r FROM public.dnm_v4_put('worklog','T4101-LOG','검증공정1','CONFIRMED',opid,log_data);wid:=r.id;
 UPDATE public.dnm_v4_records SET data=data||'{"confirmed_qty":10}' WHERE id=opid;
 UPDATE public.dnm_v42_module_access SET can_read=true,can_update=true,scope='own' WHERE profile_id=worker_id AND module='worklogs';
 PERFORM set_config('request.jwt.claim.sub',worker_id::text,true);
 result:=public.dnm_v4101_edit_status(ARRAY[wid]);PERFORM public.test_assert((result->'rows'->0->>'editable')::boolean,'owner may amend before final process completes');
 payload:=jsonb_build_object('id',wid,'version',r.version,'total',12,'defect',2,'memo','작업 중 이상 없음','reason','수량 및 메모 정정');key:=gen_random_uuid();
 result:=public.dnm_v4101_edit_work(payload,key);
 PERFORM public.test_assert((SELECT (data->>'total')::int=12 AND data->>'memo'='작업 중 이상 없음' AND (data->>'good')::int=10 FROM public.dnm_v4_records WHERE id=wid),'saved diary quantity, defect, good and memo updated');
 PERFORM public.test_assert((SELECT (data->>'confirmed_qty')::int=12 FROM public.dnm_v4_records WHERE id=opid),'operation accumulation recalculated from all confirmed logs');
 replay:=public.dnm_v4101_edit_work(payload,key);PERFORM public.test_assert(replay=result,'edit retry does not duplicate history');
 PERFORM public.test_assert((SELECT jsonb_array_length(data->'edit_history')=1 FROM public.dnm_v4_records WHERE id=wid),'edit preserves prior data once');
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_edit_work(%L::jsonb,%L::uuid)',payload||'{"memo":"다른 내용"}',key),'reused edit key with different content rejected');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=wid;
 payload:=jsonb_build_object('id',wid,'version',r.version,'reason','수정','memo','추가');
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_edit_work(%L::jsonb,gen_random_uuid())',payload||'{"total":351}'),'diary cannot exceed LOT quantity');
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_edit_work(%L::jsonb,gen_random_uuid())',payload||'{"defect":13}'),'defect cannot exceed total');
 PERFORM set_config('request.jwt.claim.sub',viewer_id::text,true);
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_edit_work(%L::jsonb,gen_random_uuid())',payload),'viewer cannot edit worklogs');
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 UPDATE public.dnm_v4_records SET state='DONE',data=data||'{"confirmed_qty":350}' WHERE id=lastid;
 UPDATE public.dnm_v4_records SET data=data-'diary_locked_at' WHERE id=rid;
 UPDATE public.dnm_v4_records SET state='WAIT' WHERE id=lastid;
 PERFORM public.test_assert(dnm_private.v4101_final_locked(rid),'legacy completed final operation retains lock when reopened by another command');
 UPDATE public.dnm_v4_records SET state='DONE' WHERE id=lastid;
 SELECT * INTO r FROM public.dnm_v4_put('worklog','T4101-LAST-LOG','최종공정','CONFIRMED',lastid,log_data||'{"total":350,"good":350,"defect":0}');lastwid:=r.id;
 PERFORM set_config('request.jwt.claim.sub',worker_id::text,true);
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_edit_work(%L::jsonb,gen_random_uuid())',payload),'final operation done locks ordinary worker edits even when route is not DONE');
 result:=public.dnm_v4101_edit_status(ARRAY[wid]);PERFORM public.test_assert(NOT(result->'rows'->0->>'editable')::boolean AND (result->'rows'->0->>'final_locked')::boolean,'final lock is reported to UI');
 PERFORM public.test_error(format('SELECT dnm_private.v410_command_guard(''cancel_work'',%L::jsonb)',jsonb_build_object('id',lastwid)),'마지막 공정');
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 PERFORM dnm_private.v410_command_guard('cancel_work',jsonb_build_object('id',lastwid));
 PERFORM public.test_assert((SELECT data->>'diary_locked_at' IS NOT NULL FROM public.dnm_v4_records WHERE id=rid),'admin legacy cancellation guard retains sticky final lock');
 result:=public.dnm_v4101_edit_work(payload,gen_random_uuid());PERFORM public.test_assert((result->>'ok')::boolean,'system admin may amend memo after final operation completion');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=lastwid;
 PERFORM public.dnm_v4_put('quality','T4101-FINAL-QA','최종 검사','CONFIRMED',oid,jsonb_build_object('stage','FINAL','total',350,'good',350,'defect',0,'route_id',rid));
 PERFORM public.test_error(format('SELECT public.dnm_v4101_edit_work(%L::jsonb,gen_random_uuid())',jsonb_build_object('id',lastwid,'version',r.version,'total',349,'reason','검사량 미만 시험')),'확정 검사수량');
 UPDATE public.dnm_v4_records SET data=data-'route_id' WHERE code='T4101-FINAL-QA';
 PERFORM public.test_error(format('SELECT public.dnm_v4101_edit_work(%L::jsonb,gen_random_uuid())',jsonb_build_object('id',lastwid,'version',r.version,'total',349,'reason','미연결 검사 시험')),'LOT 연결이 없는');
 UPDATE public.dnm_v4_records SET state='CANCELLED' WHERE code='T4101-FINAL-QA';
 result:=public.dnm_v4101_edit_work(jsonb_build_object('id',lastwid,'version',r.version,'total',349,'reason','최종수량 관리자 정정'),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='WAIT' FROM public.dnm_v4_records WHERE id=lastid),'admin quantity correction recalculates final process state');
 PERFORM public.test_assert(dnm_private.v4101_final_locked(rid),'final completion lock stays after admin reopens final process');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=wid;
 PERFORM set_config('request.jwt.claim.sub',worker_id::text,true);
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_edit_work(%L::jsonb,gen_random_uuid())',jsonb_build_object('id',wid,'version',r.version,'memo','우회','reason','시험')),'admin correction cannot reopen ordinary editing');
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 UPDATE public.dnm_v4_records SET state='CLOSED' WHERE id=oid;
 SELECT id INTO opid FROM public.dnm_v4_records WHERE kind='operation' AND parent_id=empty_route ORDER BY (data->>'seq')::int LIMIT 1;
 SELECT * INTO r FROM public.dnm_v4_put('worklog','T4101-ZERO-PENDING','미확정 작업','PENDING',opid,log_data||'{"total":0,"good":0,"defect":0}');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=empty_route;
 PERFORM public.test_error(format('SELECT public.dnm_v4101_delete(''lot'',%L::jsonb,gen_random_uuid())',jsonb_build_object('id',r.id,'version',r.version,'reason','확인 전 삭제')),'진행·확인대기');
 UPDATE public.dnm_v4_records SET state='CONFIRMED' WHERE code='T4101-ZERO-PENDING';
 UPDATE public.dnm_v4_records SET state='DONE' WHERE id=empty_route;
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=empty_route;
 result:=public.dnm_v4101_delete('lot',jsonb_build_object('id',r.id,'version',r.version,'reason','미작업 LOT 정리'),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='CANCELLED' AND data->>'deleted'='true' FROM public.dnm_v4_records WHERE id=empty_route),'zero-production LOT can be deleted under completed order');
 result:=public.dnm_v4101_balances(ARRAY[oid]);PERFORM public.test_assert((result->'rows'->0->>'remaining')::int=350,'deleted LOT allocation returns to remaining quantity');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=rid;
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_delete(''lot'',%L::jsonb,gen_random_uuid())',jsonb_build_object('id',rid,'version',r.version,'reason','검사')),'LOT with positive work cannot be deleted');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=oid;
 SELECT jsonb_agg(jsonb_build_object('id',id,'state',state,'version',version) ORDER BY id) INTO state_before FROM public.dnm_v4_records WHERE parent_id=oid;
 PERFORM public.test_4101_reject(format('SELECT public.dnm_v4101_delete(''order'',%L::jsonb,gen_random_uuid())',jsonb_build_object('id',oid,'version',r.version,'reason','검사')),'order with started production cannot be deleted');
 PERFORM public.test_assert(state_before=(SELECT jsonb_agg(jsonb_build_object('id',id,'state',state,'version',version) ORDER BY id) FROM public.dnm_v4_records WHERE parent_id=oid),'failed order deletion rolls back any zero-LOT subchanges');
 result:=public.dnm_v4101_save_order(jsonb_build_object('id',oid,'version',r.version,'data',r.data||'{"qty":1300}'),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='OPEN' FROM public.dnm_v4_records WHERE id=oid),'increasing closed civil order reopens for additional LOTs');
 result:=public.dnm_v4101_save_order(jsonb_build_object('data',jsonb_build_object('production_no','T4101-EMPTY','order_type','CIVIL','customer','시험','part_no','T4101','qty',10)),gen_random_uuid());other_order:=(result->>'id')::uuid;
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=other_order;key:=gen_random_uuid();payload:=jsonb_build_object('id',r.id,'version',r.version,'reason','미착수 오더 취소');
 result:=public.dnm_v4101_delete('order',payload,key);replay:=public.dnm_v4101_delete('order',payload,key);
 PERFORM public.test_assert(result=replay AND (SELECT state='CANCELLED' AND data->>'deleted'='true' FROM public.dnm_v4_records WHERE id=other_order),'unused order deletion preserves row and retries safely');
 PERFORM public.test_error(format('UPDATE public.dnm_v4_records SET data=data||''{"note":"legacy edit"}'' WHERE id=%L',other_order),'삭제된 수주');
END $$;
ROLLBACK;
